        /// <summary>
        /// Loại bỏ ký tự đặc biệt không hợp lệ trong tên file/thư mục
        /// </summary>
        private string SanitizeFileName(string fileName)
        {
            if (string.IsNullOrEmpty(fileName)) return "";

            string result = fileName;
            char[] invalidChars = Path.GetInvalidFileNameChars();

            for (int i = 0; i < invalidChars.Length; i++)
            {
                result = result.Replace(invalidChars[i].ToString(), "");
            }

            // Thay thế khoảng trắng liên tiếp bằng một khoảng trắng
            while (result.Contains("  "))
            {
                result = result.Replace("  ", " ");
            }

            return result.Trim();
        }

        #region ZIP Helper

        private static uint[] _crc32Table = null;
        private static object _crc32Lock = new object();

        /// <summary>
        /// Tính CRC32 cho mảng byte
        /// </summary>
        private uint ComputeCrc32(byte[] data)
        {
            if (_crc32Table == null)
            {
                lock (_crc32Lock)
                {
                    if (_crc32Table == null)
                    {
                        _crc32Table = new uint[256];
                        for (uint i = 0; i < 256; i++)
                        {
                            uint crc = i;
                            for (int j = 0; j < 8; j++)
                            {
                                if ((crc & 1) != 0)
                                    crc = (crc >> 1) ^ 0xEDB88320;
                                else
                                    crc >>= 1;
                            }
                            _crc32Table[i] = crc;
                        }
                    }
                }
            }

            uint result = 0xFFFFFFFF;
            for (int i = 0; i < data.Length; i++)
            {
                result = (result >> 8) ^ _crc32Table[(result ^ data[i]) & 0xFF];
            }
            return result ^ 0xFFFFFFFF;
        }

        /// <summary>
        /// Nén mảng byte bằng Deflate
        /// </summary>
        private byte[] DeflateCompress(byte[] data)
        {
            using (MemoryStream ms = new MemoryStream())
            {
                using (DeflateStream deflate = new DeflateStream(ms, CompressionMode.Compress, true))
                {
                    deflate.Write(data, 0, data.Length);
                }
                return ms.ToArray();
            }
        }

        /// <summary>
        /// Tạo file ZIP từ danh sách file (dùng DeflateStream, tương thích .NET 4.0)
        /// </summary>
        private void CreateZipFile(string zipFilePath, Dictionary<string, byte[]> files, string folderName)
        {
            using (FileStream fs = new FileStream(zipFilePath, FileMode.Create))
            using (BinaryWriter w = new BinaryWriter(fs))
            {
                // Lưu thông tin các entry để viết Central Directory
                List<long> headerOffsets = new List<long>();
                List<string> entryNames = new List<string>();
                List<uint> entryCrcs = new List<uint>();
                List<int> entryCompressedSizes = new List<int>();
                List<int> entryUncompressedSizes = new List<int>();

                foreach (KeyValuePair<string, byte[]> kvp in files)
                {
                    string entryName = folderName + "/" + kvp.Key;
                    byte[] data = kvp.Value;

                    // Tính CRC32
                    uint crc = ComputeCrc32(data);

                    // Nén Deflate
                    byte[] compressed = DeflateCompress(data);

                    // Ghi Local File Header
                    byte[] nameBytes = Encoding.UTF8.GetBytes(entryName);
                    long headerOffset = fs.Position;

                    w.Write((int)0x04034b50);              // signature
                    w.Write((short)20);                     // version needed
                    w.Write((short)0);                      // general purpose bit flag
                    w.Write((short)8);                      // compression method (deflate)
                    w.Write((short)0);                      // last mod time
                    w.Write((short)0);                      // last mod date
                    w.Write((uint)crc);                     // crc-32
                    w.Write((int)compressed.Length);        // compressed size
                    w.Write((int)data.Length);              // uncompressed size
                    w.Write((short)nameBytes.Length);       // file name length
                    w.Write((short)0);                      // extra field length
                    w.Write(nameBytes);                     // file name

                    // Ghi dữ liệu file đã nén
                    w.Write(compressed);

                    // Lưu thông tin cho Central Directory
                    headerOffsets.Add(headerOffset);
                    entryNames.Add(entryName);
                    entryCrcs.Add(crc);
                    entryCompressedSizes.Add(compressed.Length);
                    entryUncompressedSizes.Add(data.Length);
                }

                // Ghi Central Directory
                long centralDirOffset = fs.Position;

                for (int i = 0; i < entryNames.Count; i++)
                {
                    byte[] nameBytes = Encoding.UTF8.GetBytes(entryNames[i]);

                    w.Write((int)0x02014b50);              // signature
                    w.Write((short)20);                     // version made by
                    w.Write((short)20);                     // version needed
                    w.Write((short)0);                      // general purpose bit flag
                    w.Write((short)8);                      // compression method
                    w.Write((short)0);                      // last mod time
                    w.Write((short)0);                      // last mod date
                    w.Write((uint)entryCrcs[i]);            // crc-32
                    w.Write((int)entryCompressedSizes[i]);  // compressed size
                    w.Write(entryUncompressedSizes[i]);     // uncompressed size
                    w.Write((short)nameBytes.Length);       // file name length
                    w.Write((short)0);                      // extra field length
                    w.Write((short)0);                      // file comment length
                    w.Write((short)0);                      // disk number start
                    w.Write((short)0);                      // internal file attributes
                    w.Write((int)0);                        // external file attributes
                    w.Write((int)headerOffsets[i]);         // relative offset of local header
                    w.Write(nameBytes);                     // file name
                }

                // Ghi End of Central Directory Record
                long centralDirEnd = fs.Position;
                int entryCount = entryNames.Count;

                w.Write((int)0x06054b50);                  // signature
                w.Write((short)0);                          // number of this disk
                w.Write((short)0);                          // disk where central directory starts
                w.Write((short)entryCount);                 // number of central directory records on this disk
                w.Write((short)entryCount);                 // total number of central directory records
                w.Write((int)(centralDirEnd - centralDirOffset)); // size of central directory
                w.Write((int)centralDirOffset);             // offset of start of central directory
                w.Write((short)0);                          // comment length
            }
        }

        #endregion

        #endregion

    }
}

