/// <summary>
/// Sự kiện click nút Tải file đã chọn - tải file của nhiều học sinh được chọn
/// </summary>
protected void btnDownloadSelected_Click(object sender, EventArgs e)
{
    try
    {
        string selectedIDs = Request["iptSelect"];
        if (string.IsNullOrEmpty(selectedIDs))
        {
            MsgBox.ShowInfo("Vui lòng chọn ít nhất một học sinh để tải file!");
            return;
        }

        // Lấy danh sách ID đã chọn
        string[] arrIDs = selectedIDs.Split(',');
        List<string> validIDs = new List<string>();
        for (int i = 0; i < arrIDs.Length; i++)
        {
            string id = arrIDs[i].Trim();
            if (!string.IsNullOrEmpty(id))
            {
                validIDs.Add(id);
            }
        }

        if (validIDs.Count == 0)
        {
            MsgBox.ShowInfo("Vui lòng chọn ít nhất một học sinh để tải file!");
            return;
        }

        // Lấy dữ liệu tất cả học sinh
        InformationWebObject.WEB_StudentCollection obj = new InformationWebObject.WEB_StudentCollection();
        DataTable dtb = obj.Search(
            "@StudentCollectionStatusID", WebGlobal.ToInt32(ddlStatus.SelectedValue),
            "@FromDate", dtmFromDate.SelectedDate,
            "@ToDate", dtmToDate.SelectedDate,
            "@SpecialBranchID", WebGlobal.ToString(ddlSpecialBranch.SelectedValue));

        if (dtb == null)
        {
            MsgBox.ShowError("Lỗi truy vấn dữ liệu!");
            return;
        }

        // Đường dẫn vật lý chứa file upload
        string physicalPath = Globals.GetConfig("PhysicalDirectory_Upload") + @"\Data\StudentCollection";

        // Danh sách cột file và tên mô tả
        string[] fileColumns = new string[] {
            "File1", "File2", "File3", "File4", "File5", "File6", "File7", "File8",
            "File9", "File10", "File11", "File12", "File13", "File14", "File15", "File16"
        };

        string[] fileLabels = new string[] {
            "1. Anh CCCD_CMND mat truoc.jpg",
            "2. Anh CCCD_CMND mat sau.jpg",
            "3. Hoc ba THCS_THPT mat ngoai.jpg",
            "4. Bang TN THCS_Giay CN TN THCS.jpg",
            "5. Bang TN THPT_Giay CN TN THPT.jpg",
            "6. Bang diem trung cap.jpg",
            "7. Bang trung cap.jpg",
            "8. Giay khai sinh.jpg",
            "9. Giay chung ngoai ngu.jpg",
            "10. Bang diem hoc ba Lop 6.jpg",
            "11. Bang diem hoc ba Lop 7.jpg",
            "12. Bang diem hoc ba Lop 8.jpg",
            "13. Bang diem hoc ba Lop 9.jpg",
            "14. Bang diem hoc ba Lop 10.jpg",
            "15. Bang diem hoc ba Lop 11.jpg",
            "16. Bang diem hoc ba Lop 12.jpg"
        };

        // Gom tất cả file của các học sinh được chọn
        Dictionary<string, byte[]> filesToZip = new Dictionary<string, byte[]>();
        string parentFolderName = "Danh sach file da chon";
        int totalFileCount = 0;
        int studentWithFiles = 0;
        int studentWithoutFiles = 0;

        for (int i = 0; i < validIDs.Count; i++)
        {
            string idValue = validIDs[i];

            long idLong;
            if (!long.TryParse(idValue, out idLong)) continue;

            DataRow[] rows = dtb.Select("StudentCollectionID = " + idLong.ToString());
            if (rows.Length == 0) continue;

            DataRow row = rows[0];

            string studentID = Convert.ToString(row["StudentCollectionID"]);
            string fullName = Convert.ToString(row["FullName"]);

            // Tạo tên thư mục con: "Mã đăng ký - Tên học sinh"
            string safeSubFolder = SanitizeFileName(studentID + " - " + fullName);
            if (string.IsNullOrEmpty(safeSubFolder))
            {
                safeSubFolder = "Student_" + studentID;
            }

            int studentFileCount = 0;

            for (int j = 0; j < fileColumns.Length; j++)
            {
                string fileName = Convert.ToString(row[fileColumns[j]]);
                if (string.IsNullOrEmpty(fileName)) continue;

                string fullPath = physicalPath + @"\" + fileName;

                if (File.Exists(fullPath))
                {
                    byte[] fileData = File.ReadAllBytes(fullPath);
                    string entryName = parentFolderName + "/" + safeSubFolder + "/" + fileLabels[j];
                    // Xử lý trùng tên entry
                    string uniqueEntryName = entryName;
                    int duplicateIndex = 1;
                    while (filesToZip.ContainsKey(uniqueEntryName))
                    {
                        string ext = System.IO.Path.GetExtension(fileLabels[j]);
                        string nameWithoutExt = fileLabels[j].Replace(ext, "");
                        uniqueEntryName = parentFolderName + "/" + safeSubFolder + "/" + nameWithoutExt + "_(" + duplicateIndex.ToString() + ")" + ext;
                        duplicateIndex++;
                    }
                    filesToZip.Add(uniqueEntryName, fileData);
                    studentFileCount++;
                    totalFileCount++;
                }
            }

            if (studentFileCount > 0)
                studentWithFiles++;
            else
                studentWithoutFiles++;
        }

        if (totalFileCount == 0)
        {
            MsgBox.ShowInfo("Các học sinh được chọn chưa có file đính kèm nào!");
            return;
        }

        // Tạo file ZIP tạm thời
        string tempZipPath = System.IO.Path.GetTempPath() + Guid.NewGuid().ToString() + ".zip";

        try
        {
            CreateZipFile(tempZipPath, filesToZip, "");

            string zipFileName = HttpUtility.UrlEncode("Danh sach file da chon.zip", Encoding.UTF8);

            Response.Clear();
            Response.Buffer = true;
            Response.ContentType = "application/zip";
            Response.AddHeader("Content-Disposition", "attachment; filename=\"" + zipFileName + "\"");
            Response.TransmitFile(tempZipPath);
            Response.Flush();
            HttpContext.Current.ApplicationInstance.CompleteRequest();
        }
        finally
        {
            if (File.Exists(tempZipPath))
            {
                try { File.Delete(tempZipPath); }
                catch { }
            }
        }
    }
    catch (Exception ex)
    {
        MsgBox.ShowError("Lỗi khi tải file: " + ex.Message);
    }
}

