            "14. Bang diem hoc ba Lop 10.jpg",
            "15. Bang diem hoc ba Lop 11.jpg",
            "16. Bang diem hoc ba Lop 12.jpg"
        };

        // Gom các file tồn tại
        Dictionary<string, byte[]> filesToZip = new Dictionary<string, byte[]>();
        int fileCount = 0;

        for (int i = 0; i < fileColumns.Length; i++)
        {
            string fileName = Convert.ToString(row[fileColumns[i]]);
            if (string.IsNullOrEmpty(fileName)) continue;

            string fullPath = physicalPath + @"\" + fileName;

            if (File.Exists(fullPath))
            {
                byte[] fileData = File.ReadAllBytes(fullPath);
                string label = fileLabels[i];
                filesToZip.Add(label, fileData);
                fileCount++;
            }
        }

        if (fileCount == 0)
        {
            MsgBox.ShowInfo("Học sinh này chưa có file đính kèm nào!");
            return;
        }

        // Tạo tên thư mục an toàn: "Mã đăng ký - Tên học sinh"
        string safeFolderName = SanitizeFileName(studentCollectionID + " - " + fullName);
        if (string.IsNullOrEmpty(safeFolderName))
        {
            safeFolderName = "Student_" + studentCollectionID;
        }

        // Tạo file ZIP tạm thời
        string tempZipPath = Path.GetTempPath() + Guid.NewGuid().ToString() + ".zip";

        try
        {
            // Tạo file ZIP
            CreateZipFile(tempZipPath, filesToZip, safeFolderName);

            // Gửi file ZIP về trình duyệt
            string zipFileName = HttpUtility.UrlEncode(safeFolderName + ".zip", Encoding.UTF8);

            Response.Clear();
            Response.Buffer = true;
            Response.ContentType = "application/zip";
            Response.AddHeader("Content-Disposition", "attachment; filename=\"" + zipFileName + "\"");
            Response.TransmitFile(tempZipPath);
            Response.Flush();
            HttpContext.Current.ApplicationInstance.CompleteRequest();
        }
        finally
        {
            // Xoá file ZIP tạm
            if (File.Exists(tempZipPath))
            {
                try { File.Delete(tempZipPath); }
                catch { }
            }
        }
    }
    catch (Exception ex)
    {
        MsgBox.ShowError("Lỗi khi tải file: " + ex.Message);
    }
}

